#!/usr/bin/env node
/**
 * Generates `src/quantityData.ts` from the two quantity master tables:
 *
 *   - docs/BQs.csv — the allowed base quantities (g/ml) and their clumsiness
 *     penalties. The table is explicit for 1 … 95; values above 95 are
 *     generated by the decade rule `base (10 … 95) × 10^k` at runtime (see
 *     quantityValues.ts), so the CSV stays small.
 *   - docs/AQs.csv — the allowed additional quantities (counts), their
 *     clumsiness penalties, and one column per number scheme. A `1` marks the
 *     AQ value as allowed by that scheme. The scheme names are the same names
 *     that docs/additional_units.csv references in its `Number Scheme` column.
 *
 * The generated module is committed: the framework-free core package never
 * parses CSV at runtime. Re-run `npm run generate:quantity` after a CSV change.
 *
 * Validation is deliberately strict, because these tables drive every quantity
 * display:
 *   - positive, finite, unique values; penalties in [0, 1];
 *   - AQs parse as a number, an integer, a proper fraction or a mixed number;
 *   - BQ values are explicit only up to 95 (above that the decade rule owns the
 *     value space);
 *   - every scheme is a subset of the AQ values and stops at 30; the user's
 *     rule is that no scheme allows a count above 30.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const BQ_CSV = resolve(ROOT, 'docs/BQs.csv');
const AQ_CSV = resolve(ROOT, 'docs/AQs.csv');
const OUT_PATH = resolve(dirname(fileURLToPath(import.meta.url)), '../src/quantityData.ts');

/** Largest explicit BQ value; higher values are generated by the decade rule. */
const BQ_TABLE_MAX = 95;
/** Largest AQ value a number scheme may allow (decided with the user). */
const AQ_SCHEME_MAX = 30;
/** A value must be this close to an integer to count as one. */
const INTEGER_EPSILON = 1e-9;

/** Converts a CSV cell to a number, accepting both '.' and ',' decimals. */
function toNumber(cell) {
  return Number(cell.trim().replace(',', '.'));
}

/**
 * Parses a canonical AQ notation (`1/2`, `1+1/4`, `3`) into its numeric value.
 * Kept local so the generator is a standalone Node script (the runtime parser
 * lives in quantityValues.ts / aqLadder.ts).
 */
function parseAq(value) {
  const compact = value.replace(/\s+/g, '');
  const plus = compact.indexOf('+');
  if (plus !== -1) {
    const integer = toNumber(compact.slice(0, plus));
    const fraction = compact.slice(plus + 1);
    const slash = fraction.indexOf('/');
    return integer + toNumber(fraction.slice(0, slash)) / toNumber(fraction.slice(slash + 1));
  }
  const slash = compact.indexOf('/');
  if (slash !== -1) {
    return toNumber(compact.slice(0, slash)) / toNumber(compact.slice(slash + 1));
  }
  return toNumber(compact);
}

/** Parses a `;`-separated CSV into { header, rows } of trimmed cells. */
function parseCsv(path) {
  const text = readFileSync(path, 'utf8').replace(/^\uFEFF/, '');
  const lines = text.split(/\r?\n/).filter((line) => line.trim() !== '');
  if (lines.length === 0) {
    throw new Error(`${path}: file is empty`);
  }
  const header = lines[0].split(';').map((cell) => cell.trim());
  const rows = lines.slice(1).map((line) => {
    const cells = line.split(';').map((cell) => cell.trim());
    // Drop exactly one trailing empty cell produced by spreadsheet exports.
    if (cells.length === header.length + 1 && cells[cells.length - 1] === '') {
      cells.pop();
    }
    if (cells.length !== header.length) {
      throw new Error(
        `${path}: expected ${header.length} columns, got ${cells.length} in line: ${line}`,
      );
    }
    return cells;
  });
  return { header, rows };
}

/** Reads and validates a penalty cell. */
function parsePenalty(cell, label) {
  const value = toNumber(cell);
  if (!Number.isFinite(value) || value < 0 || value > 1) {
    throw new Error(`${label}: clumsiness penalty must be in [0, 1], got '${cell}'`);
  }
  return value;
}

/** Reads the BQ table; explicit values only, ascending, unique, at most 95. */
function buildBqValues() {
  const { header, rows } = parseCsv(BQ_CSV);
  if (header.join(';') !== 'Base Quantity;Clumsiness Penalty') {
    throw new Error(`${BQ_CSV}: unexpected header ${JSON.stringify(header)}`);
  }
  const byValue = new Map();
  for (const row of rows) {
    const value = toNumber(row[0]);
    if (!Number.isFinite(value) || value <= 0) {
      throw new Error(`${BQ_CSV}: invalid base quantity '${row[0]}'`);
    }
    if (value > BQ_TABLE_MAX) {
      throw new Error(
        `${BQ_CSV}: '${row[0]}' is above ${BQ_TABLE_MAX}; values above ${BQ_TABLE_MAX} ` +
          'are generated by the decade rule and must not be listed',
      );
    }
    if (byValue.has(value)) {
      throw new Error(`${BQ_CSV}: duplicate base quantity '${row[0]}'`);
    }
    byValue.set(value, parsePenalty(row[1], `${BQ_CSV}: ${row[0]}`));
  }
  if (byValue.size === 0) {
    throw new Error(`${BQ_CSV}: no base quantities defined`);
  }
  if (![...byValue.keys()].some((value) => value >= 10 && value <= 95)) {
    throw new Error(`${BQ_CSV}: the 10 … 95 decade base block is missing`);
  }
  return [...byValue.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([value, penalty]) => ({ value, penalty }));
}

/** Reads the AQ table plus the scheme columns; validates the scheme matrix. */
function buildAqValues() {
  const { header, rows } = parseCsv(AQ_CSV);
  if (header[0] !== 'Additional Quantity' || header[1] !== 'Clumsiness Penalty') {
    throw new Error(`${AQ_CSV}: unexpected header ${JSON.stringify(header)}`);
  }
  const schemeNames = header.slice(2);
  if (schemeNames.length === 0) {
    throw new Error(`${AQ_CSV}: no number scheme columns defined`);
  }
  if (new Set(schemeNames).size !== schemeNames.length) {
    throw new Error(`${AQ_CSV}: duplicate number scheme column names`);
  }
  for (const name of schemeNames) {
    if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(name)) {
      throw new Error(
        `${AQ_CSV}: invalid scheme name '${name}' (letters, digits, underscores; start with a letter)`,
      );
    }
  }

  const values = [];
  const schemes = new Map(schemeNames.map((name) => [name, []]));
  for (const row of rows) {
    const notation = row[0];
    const value = parseAq(notation);
    if (!Number.isFinite(value) || value <= 0) {
      throw new Error(`${AQ_CSV}: invalid additional quantity '${notation}'`);
    }
    if (values.some((entry) => Math.abs(entry.value - value) < INTEGER_EPSILON)) {
      throw new Error(`${AQ_CSV}: duplicate additional quantity '${notation}'`);
    }
    if (value > AQ_SCHEME_MAX) {
      throw new Error(
        `${AQ_CSV}: additional quantity '${notation}' is above ${AQ_SCHEME_MAX}; ` +
          'no number scheme may allow counts above 30',
      );
    }
    const penalty = parsePenalty(row[1], `${AQ_CSV}: ${notation}`);
    values.push({ value, notation, penalty });

    schemeNames.forEach((name, index) => {
      const cell = row[index + 2] ?? '';
      if (cell === '') return;
      if (cell !== '0' && cell !== '1') {
        throw new Error(
          `${AQ_CSV}: invalid scheme cell '${cell}' for '${notation}' in '${name}' (use 1, 0 or empty)`,
        );
      }
      if (cell === '1') {
        schemes.get(name).push(value);
      }
    });
  }
  if (values.length === 0) {
    throw new Error(`${AQ_CSV}: no additional quantities defined`);
  }
  values.sort((a, b) => a.value - b.value);
  // Keep each scheme's membership in AQ order (the parser may output any row
  // order; a stable, numeric order keeps the generated file diff-friendly).
  for (const list of schemes.values()) {
    list.sort((a, b) => a - b);
  }
  return { values, schemeNames, schemes };
}

/** Renders a TypeScript number with a stable, minimal decimal form. */
function number(value) {
  return String(value);
}

function render(bqValues, aq, bqMax) {
  const lines = [];
  lines.push('/**');
  lines.push(' * AUTO-GENERATED from docs/BQs.csv and docs/AQs.csv by');
  lines.push(' * scripts/generate-quantity-data.mjs.');
  lines.push(
    " * Do not edit by hand — re-run 'npm run generate:quantity' (packages/core) after a CSV change.",
  );
  lines.push(' */');
  lines.push('');
  lines.push('/** One allowed base quantity (g/ml) with its clumsiness penalty in [0, 1]. */');
  lines.push('export interface BQValue {');
  lines.push('  /** The metric value in the ingredient family unit (g or ml). */');
  lines.push('  readonly value: number;');
  lines.push('  /** 0 = perfectly clean, 1 = very awkward (docs/recipe_scaling_algorithm.md §3.1). */');
  lines.push('  readonly penalty: number;');
  lines.push('}');
  lines.push('');
  lines.push(
    `/** Explicit BQ values (1 … ${bqMax}); values above ${bqMax} are generated by the decade rule. */`,
  );
  lines.push('export const BQ_VALUES: readonly BQValue[] = [');
  for (const entry of bqValues) {
    lines.push(`  { value: ${number(entry.value)}, penalty: ${number(entry.penalty)} },`);
  }
  lines.push('];');
  lines.push('');
  lines.push(`/** Largest explicit BQ value; the decade rule starts above it. */`);
  lines.push(`export const BQ_TABLE_MAX = ${bqMax};`);
  lines.push('');
  lines.push('/** One allowed additional quantity (a count) with its penalty and notation. */');
  lines.push('export interface AQValue {');
  lines.push('  /** Numeric count (e.g. 1.25). */');
  lines.push('  readonly value: number;');
  lines.push('  /** Canonical notation used in files and display (`1+1/4`). */');
  lines.push('  readonly notation: string;');
  lines.push('  /** 0 = perfectly clean, 1 = very awkward (docs/recipe_scaling_algorithm.md §3.2). */');
  lines.push('  readonly penalty: number;');
  lines.push('}');
  lines.push('');
  lines.push('/** Allowed AQ values, ascending. */');
  lines.push('export const AQ_VALUES: readonly AQValue[] = [');
  for (const entry of aq.values) {
    lines.push(
      `  { value: ${number(entry.value)}, notation: ${JSON.stringify(entry.notation)}, ` +
        `penalty: ${number(entry.penalty)} },`,
    );
  }
  lines.push('];');
  lines.push('');
  lines.push('/** Scheme names, in the column order of docs/AQs.csv. */');
  lines.push(
    `export const AQ_SCHEME_NAMES: readonly string[] = [${aq.schemeNames
      .map((name) => JSON.stringify(name))
      .join(', ')}];`,
  );
  lines.push('');
  lines.push('/** Allowed AQ values per number scheme, ascending. */');
  lines.push('export const AQ_SCHEMES: Readonly<Record<string, readonly number[]>> = {');
  for (const name of aq.schemeNames) {
    const values = aq.schemes.get(name).map((value) => number(value)).join(', ');
    lines.push(`  ${JSON.stringify(name)}: [${values}],`);
  }
  lines.push('};');
  lines.push('');
  return lines.join('\n');
}

const bqValues = buildBqValues();
const aq = buildAqValues();
let output = render(bqValues, aq, BQ_TABLE_MAX);
try {
  const { format, resolveConfig } = await import('prettier');
  const config = await resolveConfig(OUT_PATH);
  output = await format(output, { ...config, parser: 'typescript' });
} catch {
  // Prettier not installed — the raw render is still valid TypeScript.
}
writeFileSync(OUT_PATH, output, 'utf8');
console.log(
  `Wrote ${bqValues.length} BQ value(s), ${aq.values.length} AQ value(s), ` +
    `${aq.schemeNames.length} scheme(s) to ${OUT_PATH}`,
);
